{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C06"],
      "claim": "Metoclopramide, a basic amine with P-gp efflux liability, shows good passive BBB permeability and appreciable brain distribution in humans even when P-gp is functional, supporting that similar ionization and efflux features do not preclude CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Human PET imaging of metoclopramide gave a baseline brain distribution of 2.1 mL/cm3, described as substantial baseline brain uptake, providing direct human evidence of meaningful CNS penetration despite transporter-mediated efflux.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Fenbendazole-related compound was detected in pig CSF within 10 minutes and is described as crossing the BBB mainly by passive diffusion without being a P-gp or OATP substrate, demonstrating that aromatic heterocycles with carbamate and polar groups can achieve rapid CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Urolithin B was detected in rat brain after intravenous administration, confirming that a polar aromatic lactone with phenolic groups can cross the BBB.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Urolithin A was found in mouse brain after oral and intraperitoneal administration, providing in vivo evidence that a polar polyphenolic metabolite can achieve brain distribution.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Apocynin readily crosses the BBB in mice with logBB values between -0.04 and 1, showing that a small aromatic ketone with moderate polarity can have meaningful brain penetration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Paeonol was detected in rat brain after administration, confirming BBB passage despite rapid clearance, and supporting CNS access for aromatic compounds with polar substituents.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Remacemide was detected in human and canine cerebrospinal fluid, providing direct evidence of CNS access for a lipophilic amine-containing drug.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "All transferred experimental evidence supports meaningful CNS access for the query molecule. The physicochemical prior indicates ionization and possible efflux, but direct analogue evidence, especially metoclopramide and fenbendazole-related compounds, shows that such liabilities do not prevent adequate brain penetration.",
  "evidence_gaps": [
    "No direct brain, CSF, or PET measurement exists for the query molecule itself.",
    "The query's transporter phenotype is inferred from structure and not experimentally confirmed.",
    "Quantitative unbound brain-to-plasma ratio or CNS exposure metrics are unavailable for the query."
  ],
  "new_evidence_assessment": [
    {
      "applicability": "high",
      "card_ids": ["C06", "C11"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "basic amine P-gp substrate with good CNS penetration"
    },
    {
      "applicability": "high",
      "card_ids": ["C09"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "passive diffusion CNS access"
    },
    {
      "applicability": "moderate",
      "card_ids": ["C10", "C07", "C14", "C01", "C12"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "small polar aromatic CNS penetrants"
    }
  ],
  "revision_action": "initial"
}

